PASSWORD_SQL = """
        UPDATE doctors
        SET password_hash = '$2b$10$jsU1EogKnBAb780EQNvCReE07NCwHxKZv4gS9BS8TPWW3nmL2ZonG'
        WHERE doctor_serial_number = 'Dsn90mA2';
    """

FETCH_NOTES_SQL = """
    SELECT cn.note_id, v.patient_serial_number, cn.note_text, cn.created_at::date
    FROM clinical_notes cn
    JOIN visits v ON v.visit_id = cn.visit_id
    WHERE v.doctor_serial_number = %s
"""

FETCH_CHIEF_COMPLAINTS_SQL = """
    SELECT v.visit_id, v.patient_serial_number, v.chief_complaint, v.visit_date::date
    FROM visits v
    WHERE v.doctor_serial_number = %s AND v.chief_complaint IS NOT NULL
"""


def _already_seeded(conn) -> bool:
    with conn.cursor() as cur:
        cur.execute("SELECT count(*) FROM patients")
        
        return cur.fetchone()[0] > 0


def main() -> None:
    with psycopg.connect(_conninfo(), autocommit=False) as conn:
        if _already_seeded(conn):
            print("seed_demo_data: patients table already populated - skipping.")
            return

        with conn.cursor() as cur:
            cur.execute(SEED_SQL)
            counts = cur.fetchone()
            cur.execute(PASSWORD_SQL)
            cur.execute(FETCH_NOTES_SQL, (SEED_DOCTOR_SERIAL,))
            notes = cur.fetchall()
            cur.execute(FETCH_CHIEF_COMPLAINTS_SQL, (SEED_DOCTOR_SERIAL,))
            chief_complaints = cur.fetchall()

        conn.commit()
        print(f"seed_demo_data: inserted {counts}")

    for note_id, patient_serial, note_text, record_date in notes:
        rag.add_patient_note(
            patient_serial=patient_serial,
            note_id=str(note_id),
            note_summary=note_text,
            record_date=str(record_date),
        )

    for visit_id, patient_serial, chief_complaint, record_date in chief_complaints:
        rag.add_chief_complaint(
            patient_serial=patient_serial,
            visit_id=str(visit_id),
            chief_complaint=chief_complaint,
            record_date=str(record_date),
        )

    print(f"seed_demo_data: indexed {len(notes)} notes and {len(chief_complaints)} chief complaints into Chroma.")


if __name__ == "__main__":
    main()
